function Workspace({ onExit }: { onExit: () => void }) {
  const { user, logout, isAuthenticated } = useAuth();
  const [view, setView] = useState("overview");
  const [mobileNav, setMobileNav] = useState(false);
  const [saved, setSaved] = useState<number[]>([2]);
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("All"); const [province, setProvince] = useState("All"); const [promptOpen, setPromptOpen] = useState(false);
  const [profileComplete, setProfileComplete] = useState(false); const [profileOpen, setProfileOpen] = useState(false); const [profileDraft, setProfileDraft] = useState({ country: "South Africa", education: "", province: "", location: "", goal: "", interests: "", skills: "", experience: "", constraints: "", resources: "" });
  const [chat, setChat] = useState([{ from: "ai", text: "Hi there. I’m here to help you find a next step that feels realistic — not overwhelming. What are you most curious about right now?" }]); const [conversationId, setConversationId] = useState<number | undefined>(); const [pathwayDraft, setPathwayDraft] = useState<any>(null);
  const [savedForConversationId, setSavedForConversationId] = useState<number | undefined>(undefined);
  const savePathwayMutation = trpc.pathways.save.useMutation();
  const pathwaySaveStatus: "idle" | "saving" | "saved" = savePathwayMutation.isPending ? "saving" : conversationId !== undefined && savedForConversationId === conversationId ? "saved" : "idle";
  const [input, setInput] = useState("");
  // Starts empty — this must render only the authenticated user's own real applications
  // (synced below from applicationList.data), never placeholder/demo entries.
  const [applications, setApplications] = useState<any[]>([]);
  const searchInput = { query: query || "South Africa youth opportunities", category: category === "All" ? undefined : category, province: province === "All" ? undefined : province }; const remoteOpportunities = trpc.opportunities.list.useQuery({ search: query || undefined, category: category === "All" ? undefined : category as "Study" | "Work" | "Skills" | "Business", province: province === "All" ? undefined : province }); const liveSearch = trpc.opportunities.liveSearch.useQuery(searchInput, { staleTime: 60000 });
  const profileQuery = trpc.profile.get.useQuery(undefined, { enabled: isAuthenticated }); const saveProfile = trpc.profile.save.useMutation(); const promptLibrary = trpc.prompts.list.useQuery(); const savedList = trpc.opportunities.saved.useQuery(undefined, { enabled: isAuthenticated }); const conversationList = trpc.conversations.list.useQuery(undefined, { enabled: isAuthenticated }); const conversationUtils = trpc.useUtils(); const createConversation = trpc.conversations.create.useMutation(); const saveOpportunityMutation = trpc.opportunities.save.useMutation();
  const guideReply = trpc.guide.respond.useMutation();
  const applicationList = trpc.applications.list.useQuery(undefined, { enabled: isAuthenticated }); const pathwayList = trpc.pathways.list.useQuery(undefined, { enabled: isAuthenticated }); const [selectedPathwayId, setSelectedPathwayId] = useState<number | undefined>(undefined); const activePathwayId = selectedPathwayId ?? pathwayList.data?.[0]?.id; const checklistQuery = trpc.pathways.checklist.useQuery({ pathwayId: activePathwayId || 0 }, { enabled: isAuthenticated && Boolean(activePathwayId) }); const toggleChecklist = trpc.pathways.toggleChecklist.useMutation();
  const createApplication = trpc.applications.create.useMutation(); const updateApplication = trpc.applications.update.useMutation(); const generateDraft = trpc.drafts.generate.useMutation();
  const displayName = user?.name?.split(" ")[0] || "there"; const fitReasons = [profileDraft.interests, profileDraft.skills, profileDraft.goal].filter(Boolean).join(" · ") || "curiosity · problem-solving · room to grow"; const profileFields = ["goal", "education", "interests", "skills", "experience", "location", "constraints", "resources"] as const; const completion = Math.round(profileFields.filter(field => Boolean(profileDraft[field]?.trim())).length / profileFields.length * 100); useEffect(() => { if (profileQuery.data) { const data = profileQuery.data; setProfileDraft(current => ({ ...current, country: data.country ?? "South Africa", education: data.education ?? "", province: data.province ?? "", location: data.location ?? "", goal: data.goal ?? "", interests: data.interests ?? "", skills: data.skills ?? "", experience: data.experience ?? "", constraints: data.constraints ?? "", resources: data.resources ?? "" })); } }, [profileQuery.data]); useEffect(() => { setProfileComplete(completion === 100); }, [completion]); useEffect(() => { if (applicationList.data) setApplications(applicationList.data.map(item => ({ id: item.id, title: item.title, org: item.organisation, type: item.type, deadline: item.deadlineDate ? new Date(item.deadlineDate).toLocaleDateString() : "No deadline", deadlineDate: item.deadlineDate ? new Date(item.deadlineDate) : null, status: item.status, dateApplied: item.dateApplied ? new Date(item.dateApplied).toLocaleDateString() : undefined, notes: item.notes || undefined }))); }, [applicationList.data]);
  const [nowTick, setNowTick] = useState(() => Date.now());
  const today = new Date(nowTick);
  useEffect(() => { const id = setInterval(() => setNowTick(Date.now()), 5 * 60 * 1000); return () => clearInterval(id); }, []);
  const upcomingDeadlines = useMemo(() => getUpcomingDeadlines(applications, DEADLINE_REMINDER_DAYS, new Date(nowTick)), [applications, nowTick]);
  // Dismissing a reminder only silences it for the rest of the current 8-hour
  // slot (00:00 / 08:00 / 16:00) — it isn't gone for good, so a still-open
  // deadline resurfaces on its own at the next checkpoint instead of staying
  // hidden indefinitely.
  const currentReminderSlot = getReminderSlotKey(new Date(nowTick));
  const [dismissedSlotById, setDismissedSlotById] = useState<Record<string, string>>(() => { try { const stored = JSON.parse(localStorage.getItem("pf_dismissed_deadline_slots") || "{}"); return stored && typeof stored === "object" && !Array.isArray(stored) ? stored : {}; } catch { return {}; } });
  const bannerDeadlines = upcomingDeadlines.filter(d => dismissedSlotById[d.id] !== currentReminderSlot);
  const dismissDeadline = (id: string) => setDismissedSlotById(current => { const next = { ...current, [id]: currentReminderSlot }; try { localStorage.setItem("pf_dismissed_deadline_slots", JSON.stringify(next)); } catch { /* private browsing or storage disabled — dismissal just won't persist */ } return next; });
  const curatedOpportunities = remoteOpportunities.data?.length ? remoteOpportunities.data.map((o, i) => ({ id: o.id, category: o.category, title: o.name, org: o.organisation, place: `${o.province || "National"} · Curated`, desc: o.description, tags: (o.traits || "verified opportunity").split(",").slice(0, 2), deadline: o.deadlineDate ? new Date(o.deadlineDate).toLocaleDateString() : "Rolling", sourceUrl: o.sourceUrl, score: Math.max(68, 94 - i * 4), tone: o.category === "Work" ? "blue" : o.category === "Skills" ? "green" : o.category === "Business" ? "violet" : "teal", source: "curated" })) : opportunities.map(o => ({ ...o, sourceUrl: o.category === "Study" ? "https://www.nsfas.org.za/" : o.category === "Work" ? "https://sayouth.mobi/" : o.category === "Business" ? "https://www.seda.org.za/" : "https://mict.org.za/bursaries/", source: "curated" })); const liveCards = (liveSearch.data?.results || []).map((o, i) => ({ id: -1000 - i, category: o.category, title: o.name, org: o.organisation, place: `${o.province || "National"} · Live search`, desc: o.description, tags: (o.traits || "Live result,verify source").split(",").slice(0, 2), deadline: "Verify source", sourceUrl: o.sourceUrl, score: Math.max(68, 88 - i * 3), tone: o.category === "Work" ? "blue" : o.category === "Skills" ? "green" : o.category === "Business" ? "violet" : "teal", source: "live" })); const displayOpportunities = [...liveCards, ...curatedOpportunities]; const sourceMessage = (liveSearch.data?.fallback ? liveSearch.data.message : liveCards.length ? liveSearch.data?.message : "From PathFinder's curated list — verify before applying.") || "From PathFinder's curated list — verify before applying.";
  const filtered = useMemo(() => displayOpportunities.filter(o => (category === "All" || o.category === category) && `${o.title} ${o.org} ${o.tags.join(" ")}`.toLowerCase().includes(query.toLowerCase())), [displayOpportunities, query, category]);
  const nav = [{ id: "overview", label: "Overview", icon: Compass }, { id: "chat", label: "Career guide", icon: MessageCircle }, { id: "opportunities", label: "Search opportunities", icon: Search }, { id: "plan", label: "My Pathways", icon: Target }, { id: "applications", label: "Applications", icon: BriefcaseBusiness }, ...(user?.role === "admin" ? [{ id: "admin", label: "Manage opportunities", icon: Settings2 }] : [])];
  async function send(text = input) { if (!text.trim()) return; const next = [...chat, { from: "user", text }]; setChat(next); setInput(""); setView("chat"); if (isAuthenticated) { try { let activeConversation = conversationId; if (!activeConversation) { const created = await createConversation.mutateAsync({ title: text.slice(0, 70) }); activeConversation = created?.id; setConversationId(activeConversation); } const result = await guideReply.mutateAsync({ profile: JSON.stringify(profileDraft), history: next.map(m => ({ role: m.from === "ai" ? "assistant" : "user", content: m.text })), message: text, conversationId: activeConversation }); setPathwayDraft(result.pathwayDraft ?? null); if (result.profileUpdates && Object.keys(result.profileUpdates).length) { setProfileDraft(current => ({ ...current, ...result.profileUpdates })); conversationUtils.profile.get.invalidate(); } setChat(c => [...c, { from: "ai", text: result.message }]); } catch { setChat(c => [...c, { from: "ai", text: "I’m having a little trouble connecting right now. You can still explore the opportunity hub while we reconnect." }]); } } else { setChat(c => [...c, { from: "ai", text: "That’s useful context. I’m hearing that you want something practical, with room to grow. Which matters more right now: getting started quickly, or building towards a longer-term qualification?" }]); } }
  // The one deterministic way a pathway gets saved: a direct click, gated on a real ready
  // pathway object existing for this conversation — never inferred from chat wording.
  async function handleSavePathway() {
    if (!conversationId || !canOfferSavePathway(pathwayDraft) || pathwaySaveStatus !== "idle") return;
    const result = await savePathwayMutation.mutateAsync({ conversationId });
    if (result) {
      setSavedForConversationId(conversationId);
      setChat(c => [...c, { from: "ai", text: "Your pathway has been saved — you can find it under My Pathways." }]);
      await Promise.all([conversationUtils.pathways.list.invalidate(), conversationUtils.pathways.checklist.invalidate()]);
    }
  }
  return <div className="min-h-screen bg-[#f7fafc] text-[#183b56]">{mobileNav && <div className="fixed inset-0 z-20 bg-[#183b56]/40 backdrop-blur-[1px] lg:hidden" onClick={() => setMobileNav(false)} />}<aside className={`fixed inset-y-0 left-0 z-30 flex w-[272px] flex-col border-r border-[#e0ecec] bg-white p-6 transition-transform lg:translate-x-0 ${mobileNav ? "translate-x-0" : "-translate-x-full"}`}><div className="flex items-center justify-between"><Logo /><button aria-label="Close menu" className="lg:hidden" onClick={() => setMobileNav(false)}><X size={20} /></button></div><div className="mt-12 rounded-[18px] bg-[#e8f6f3] p-4"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-full bg-[#0d9488] text-white"><Sparkles size={18} /></div><div><p className="text-xs font-bold uppercase tracking-[.12em] text-[#0f766e]">Your direction</p><p className="mt-1 text-sm font-bold text-[#183b56]">Let’s find it together</p></div></div><div className="mt-4 h-1.5 rounded-full bg-white"><div className="h-full rounded-full bg-[#0d9488]" style={{ width: `${completion}%` }} /></div><p className="mt-2 text-[11px] text-[#52717d]">Profile {completion}% complete</p></div><nav className="mt-10 space-y-1">{nav.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => { setView(id); setMobileNav(false); }} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm font-bold transition ${view === id ? "bg-[#e8f6f3] text-[#0f766e]" : "text-[#6c8490] hover:bg-[#f7fafc]"}`}><Icon size={18} />{label}{id === "applications" && <span className="ml-auto flex h-5 min-w-5 items-center justify-center rounded-full bg-[#fff0ea] px-1.5 text-[10px] text-[#d95d3f]">{applications.length}</span>}</button>)}</nav><div className="mt-auto border-t border-[#e8eeee] pt-5"><button onClick={() => { logout(); onExit(); }} className="flex w-full items-center gap-3 px-3 py-3 text-sm font-bold text-[#6c8490]"><UserRound size={18} />{displayName}<MoreHorizontal size={17} className="ml-auto" /></button></div></aside><div className="lg:pl-[272px]"><header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-[#e0ecec] bg-[#f7fafc]/90 px-4 backdrop-blur-md sm:px-8"><button aria-label="Open menu" className="lg:hidden" onClick={() => setMobileNav(true)}><Menu /></button><div className="hidden lg:block">{view === "overview" ? <p className="text-sm font-semibold text-[#8aa0a8]">{today.toLocaleDateString(undefined, { weekday: "long", day: "2-digit", month: "long", year: "numeric" })}</p> : <p className="text-sm font-semibold text-[#8aa0a8]">Your PathFinder workspace</p>}</div><div className="flex items-center gap-3"><button aria-label="Upcoming deadlines" onClick={() => setView("applications")} className="relative flex h-10 w-10 items-center justify-center rounded-full bg-white text-[#52717d] card-border">{bannerDeadlines.length > 0 && <span className={`absolute -right-1 -top-1 flex h-5 min-w-5 items-center justify-center rounded-full px-1 text-[10px] font-bold text-white ${bannerDeadlines.some(d => d.urgent) ? "bg-[#ff7a59]" : "bg-[#2563eb]"}`}>{bannerDeadlines.length}</span>}<Bell size={17} /></button><button aria-label="Open saved opportunities" onClick={() => setView("saved")} className="flex h-10 w-10 items-center justify-center rounded-full bg-white text-[#52717d] card-border"><Heart size={17} /></button><button aria-label="Open editable profile" onClick={() => setProfileOpen(true)} className="flex h-10 w-10 items-center justify-center rounded-full bg-[#183b56] text-sm font-bold text-white">{displayName.slice(0,1).toUpperCase()}</button></div></header><main className="w-full max-w-none px-4 py-6 sm:px-6 lg:px-8 xl:px-10">{view === "admin" && user?.role === "admin" && <AdminOpportunities />}{view === "overview" && <Overview name={displayName} profileGoal={profileDraft.goal} fitReasons={fitReasons} persistedDirection={pathwayList.data?.[0]?.recommendedDirection || "Digital pathways with purpose"} onView={setView} profileComplete={profileComplete} onStart={() => setProfileOpen(true)} upcomingDeadlines={upcomingDeadlines} bannerDeadlines={bannerDeadlines} onDismissDeadline={dismissDeadline} />}{view === "saved" && <SavedPage savedItems={savedList.data || []} onToggle={async item => { let snap: any = {}; try { snap = JSON.parse(item.snapshotData || "{}"); } catch {} if (isAuthenticated) { await saveOpportunityMutation.mutateAsync({ opportunityId: item.opportunityId ?? undefined, snapshotData: JSON.stringify(snap) }); await conversationUtils.opportunities.saved.invalidate(); } }} />}{view === "chat" && <Chat chat={chat} input={input} setInput={setInput} send={send} pathwayDraft={pathwayDraft} onSavePathway={handleSavePathway} pathwaySaveStatus={pathwaySaveStatus} prompts={promptLibrary.data || []} promptOpen={promptOpen} setPromptOpen={setPromptOpen} conversations={conversationList.data || []} onOpenConversation={async (id) => { const rows = await conversationUtils.conversations.messages.fetch({ conversationId: id }); setConversationId(id); setChat(rows.map(m => ({ from: m.sender === "assistant" ? "ai" : "user", text: m.message }))); }} onNewChat={async () => { setChat([{ from: "ai", text: "Fresh start. What would you like to explore today?" }]); setPathwayDraft(null); const created = await createConversation.mutateAsync({ title: "New career conversation" }); setConversationId(created?.id); }} />}{view === "opportunities" && <Opportunities sourceMessage={sourceMessage} filtered={filtered} query={query} setQuery={setQuery} category={category} setCategory={setCategory} province={province} setProvince={setProvince} saved={[...saved, ...(savedList.data || []).flatMap(x => { let snap: any = {}; try { snap = JSON.parse(x.snapshotData || "{}"); } catch {} return [x.opportunityId, snap.sourceUrl]; }).filter((x): x is number | string => typeof x === "number" || typeof x === "string")]} savedItems={savedList.data || []} toggleSave={async (id) => { const item = displayOpportunities.find(o => o.id === id); if (item && isAuthenticated) { const result = await saveOpportunityMutation.mutateAsync({ opportunityId: typeof id === "number" ? id : undefined, snapshotData: JSON.stringify(item) }); setSaved(s => result.saved ? Array.from(new Set([...s, id])) : s.filter(x => x !== id)); await conversationUtils.opportunities.saved.invalidate(); } else { setSaved(s => s.includes(id) ? s.filter(x => x !== id) : [...s, id]); } }} />}{view === "plan" && <Plan setView={setView} savedPathways={pathwayList.data || []} selectedPathwayId={activePathwayId} onSelectPathway={setSelectedPathwayId} checklist={checklistQuery.data || []} onToggleChecklist={async (id, complete) => { await toggleChecklist.mutateAsync({ itemId: id, isComplete: complete }); await checklistQuery.refetch(); }} />}{view === "applications" && <Applications applications={applications} setApplications={setApplications} savedOpportunities={savedList.data || []} onEditApplication={async (index, form) => { const item = applications[index]; if (isAuthenticated && item?.id) await updateApplication.mutateAsync({ id: item.id, ...form }); setApplications(list => list.map((x, i) => i === index ? { ...x, org: form.organisation, title: form.title, type: form.type, deadline: form.deadlineDate ? form.deadlineDate.toLocaleDateString() : "No deadline", deadlineDate: form.deadlineDate || null, status: form.status || "Not started", dateApplied: form.dateApplied?.toLocaleDateString(), notes: form.notes } : x)); }} onUpdateStatus={async (item, status) => { const previous = item.status; setApplications(list => list.map(x => x === item ? { ...x, status } : x)); try { if (isAuthenticated && item.id) await updateApplication.mutateAsync({ id: item.id, status: status as any }); } catch { setApplications(list => rollbackApplicationStatus(list, item, previous)); } }} onSaveApplication={async form => { const savedItem = { title: form.title, org: form.organisation, type: form.type, deadline: form.deadlineDate ? form.deadlineDate.toLocaleDateString() : "No deadline", deadlineDate: form.deadlineDate || null, status: form.status || "Not started", dateApplied: form.dateApplied?.toLocaleDateString(), notes: form.notes }; setApplications(a => [...a, savedItem]); if (isAuthenticated) await createApplication.mutateAsync(form); }} onGenerateDraft={async (selectedIndex) => { const result = await generateDraft.mutateAsync({ opportunity: JSON.stringify(applications[selectedIndex] || {}), profile: JSON.stringify(profileDraft), draftType: applications[selectedIndex]?.type === "Study" ? "study" : "work" }); return result.draft; }} />}</main>{profileOpen && <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#183b56]/35 p-4 backdrop-blur-sm"><div className="max-h-[90vh] w-full max-w-[720px] overflow-y-auto rounded-[26px] bg-white p-5 shadow-2xl sm:p-8"><div className="flex items-start justify-between"><div><Pill color="teal">Your context</Pill><h2 className="font-display mt-4 text-3xl">Let’s make this personal.</h2><p className="mt-2 text-sm leading-6 text-[#6c8490]">A few details help us suggest directions that fit your reality.</p></div><button onClick={() => setProfileOpen(false)} className="text-[#8aa0a8]"><X size={20} /></button></div><div className="mt-6 grid gap-4 sm:grid-cols-2"><label className="text-sm font-bold">Country<select value={profileDraft.country} onChange={e => setProfileDraft({ ...profileDraft, country: e.target.value })} className="mt-2 h-11 w-full rounded-xl border border-[#dce9ea] bg-white px-3 text-sm font-normal outline-none focus:border-[#0d9488]"><option>South Africa</option><option>Other</option></select></label><label className="text-sm font-bold">Education level<select value={profileDraft.education} onChange={e => setProfileDraft({ ...profileDraft, education: e.target.value })} className="mt-2 h-11 w-full rounded-xl border border-[#dce9ea] bg-white px-3 text-sm font-normal outline-none focus:border-[#0d9488]"><option value="">Choose one</option><option>High school / matric</option><option>TVET student</option><option>University student</option><option>Graduate</option><option>Not currently studying</option></select></label><label className="text-sm font-bold">Province<select value={profileDraft.province} onChange={e => setProfileDraft({ ...profileDraft, province: e.target.value })} className="mt-2 h-11 w-full rounded-xl border border-[#dce9ea] bg-white px-3 text-sm font-normal outline-none focus:border-[#0d9488]"><option value="">Choose one</option><option>Gauteng</option><option>Western Cape</option><option>KwaZulu-Natal</option><option>Eastern Cape</option><option>Other / online</option></select></label><label className="text-sm font-bold sm:col-span-2">Where are you based?<input value={profileDraft.location} onChange={e => setProfileDraft({ ...profileDraft, location: e.target.value })} placeholder="e.g. Soweto, Johannesburg" className="mt-2 h-11 w-full rounded-xl border border-[#dce9ea] px-3 text-sm font-normal outline-none focus:border-[#0d9488]" /></label><label className="text-sm font-bold sm:col-span-2">What do you want more of right now?<input value={profileDraft.goal} onChange={e => setProfileDraft({ ...profileDraft, goal: e.target.value })} placeholder="e.g. a first job, a qualification, practical skills" className="mt-2 h-11 w-full rounded-xl border border-[#dce9ea] px-3 text-sm font-normal outline-none focus:border-[#0d9488]" /></label><label className="text-sm font-bold">Interests<textarea value={profileDraft.interests} onChange={e => setProfileDraft({ ...profileDraft, interests: e.target.value })} placeholder="e.g. people, design, technology" className="mt-2 min-h-[88px] w-full rounded-xl border border-[#dce9ea] p-3 text-sm font-normal outline-none focus:border-[#0d9488]" /></label><label className="text-sm font-bold">Existing skills<textarea value={profileDraft.skills} onChange={e => setProfileDraft({ ...profileDraft, skills: e.target.value })} placeholder="e.g. writing, fixing things, organising" className="mt-2 min-h-[88px] w-full rounded-xl border border-[#dce9ea] p-3 text-sm font-normal outline-none focus:border-[#0d9488]" /></label><label className="text-sm font-bold">Experience<textarea value={profileDraft.experience} onChange={e => setProfileDraft({ ...profileDraft, experience: e.target.value })} placeholder="e.g. volunteering, projects, part-time work" className="mt-2 min-h-[88px] w-full rounded-xl border border-[#dce9ea] p-3 text-sm font-normal outline-none focus:border-[#0d9488]" /></label><label className="text-sm font-bold">Constraints<textarea value={profileDraft.constraints} onChange={e => setProfileDraft({ ...profileDraft, constraints: e.target.value })} placeholder="e.g. transport, time, device or access constraints" className="mt-2 min-h-[88px] w-full rounded-xl border border-[#dce9ea] p-3 text-sm font-normal outline-none focus:border-[#0d9488]" /></label><label className="text-sm font-bold">Resources<textarea value={profileDraft.resources} onChange={e => setProfileDraft({ ...profileDraft, resources: e.target.value })} placeholder="e.g. laptop, internet, mentor or support" className="mt-2 min-h-[88px] w-full rounded-xl border border-[#dce9ea] p-3 text-sm font-normal outline-none focus:border-[#0d9488]" /></label></div><div className="mt-6 flex justify-end gap-3"><Button variant="ghost" onClick={() => setProfileOpen(false)}>Not now</Button><Button onClick={async () => { if (isAuthenticated) { await saveProfile.mutateAsync(profileDraft); } setProfileComplete(true); setProfileOpen(false); }}>Save my profile <Check size={16} /></Button></div></div></div>}</div></div>;
}
function Overview({ name, profileGoal, fitReasons, persistedDirection, onView, profileComplete, onStart, upcomingDeadlines = [], bannerDeadlines = upcomingDeadlines, onDismissDeadline }: { name: string; profileGoal?: string; fitReasons: string; persistedDirection: string; onView: (v: string) => void; profileComplete: boolean; onStart: () => void; upcomingDeadlines?: any[]; bannerDeadlines?: any[]; onDismissDeadline?: (id: string) => void }) { const bannerItem = bannerDeadlines[0]; return <div>{bannerItem &&<div className={`mb-6 flex flex-wrap items-center justify-between gap-3 rounded-2xl p-4 text-sm font-semibold ${bannerItem.urgent ? "bg-[#fff0ea] text-[#d95d3f]" : "bg-[#e8f6f3] text-[#0f766e]"}`}><div className="flex items-center gap-3"><Timer size={18} /><span>Your {bannerItem.title} deadline is {bannerItem.daysRemaining === 0 ? "today" : bannerItem.daysRemaining === 1 ? "tomorrow" : `in ${bannerItem.daysRemaining} days`}.{bannerDeadlines.length > 1 && ` ${bannerDeadlines.length - 1} more coming up.`}</span></div><div className="flex items-center gap-2"><button onClick={() => onView("applications")} className="rounded-full bg-white/70 px-3 py-1.5 text-xs font-bold">View applications</button><button aria-label="Dismiss deadline reminder" onClick={() => onDismissDeadline?.(bannerItem.id)} className="text-current/70 hover:text-current"><X size={16} /></button></div></div>}<div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><PathMarker label="Your workspace" /><h1 className="font-display mt-4 text-4xl tracking-[-.045em] sm:text-5xl">Hi {name}, <span className="text-[#0d9488]">let’s get moving.</span></h1><p className="mt-3 text-[#6c8490]">You don’t need the whole map. Just a direction for today.</p></div><Button variant="outline" onClick={() => onView("chat")}><MessageCircle size={17} /> Talk to your guide</Button></div><div className="mt-10 grid gap-5 lg:grid-cols-[1.25fr_.75fr]"><div className="rounded-[26px] bg-[#183b56] p-7 text-white shadow-xl shadow-[#183b56]/10"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-white/45">Recommended direction</p><h2 className="font-display mt-3 text-3xl">{persistedDirection}</h2><p className="mt-3 max-w-[500px] leading-7 text-white/65">{profileGoal ? `Built around what you shared: ${profileGoal}. This is a direction worth exploring with one practical next move.` : "Based on your curiosity about technology and wanting work that creates options, this is a strong direction worth exploring."}</p></div><div className="hidden h-14 w-14 items-center justify-center rounded-2xl bg-[#0d9488] sm:flex"><Sparkles size={24} /></div></div><div className="mt-7 flex flex-wrap items-center gap-5"><div><p className="text-3xl font-bold">87%</p><p className="text-xs text-white/45">transparent match</p></div><div className="h-9 w-px bg-white/15" /><div className="text-sm text-white/70"><span className="font-bold text-[#8de3d6]">Why it fits:</span> {fitReasons}</div></div><div className="mt-7 flex flex-wrap gap-3"><Button variant="light" onClick={() => onView("plan")}>View your pathway <ArrowRight size={16} /></Button><button onClick={() => onView("chat")} className="rounded-full px-4 text-sm font-bold text-white/60 hover:bg-white/10 hover:text-white">Continue chatting</button></div></div><div className="rounded-[26px] bg-white p-7 card-border"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#8aa0a8]">Your profile</p><h3 className="mt-2 text-lg font-bold">Make your matches sharper</h3></div><div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#fff6dc] text-[#bc8610]"><PenLine size={19} /></div></div><p className="mt-4 text-sm leading-6 text-[#6c8490]">Tell us a little more about your context and we’ll make the next suggestions more personal.</p><button onClick={onStart} className="mt-6 flex w-full items-center justify-between rounded-xl bg-[#f7fafc] p-3 text-left text-sm font-bold text-[#0f766e]"><span>{profileComplete ? "Profile saved" : "Complete your profile"}</span>{profileComplete ? <Check size={17} /> : <ChevronRight size={17} />}</button></div></div><div className="mt-10 flex items-end justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#8aa0a8]">Start somewhere</p><h2 className="font-display mt-2 text-3xl tracking-[-.03em]">What are you exploring?</h2></div><button onClick={() => onView("opportunities")} className="hidden text-sm font-bold text-[#0f766e] sm:block">Browse all <ArrowRight size={15} className="ml-1 inline" /></button></div><div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{pathways.map(({ icon: Icon, label, copy, tint }) => <button key={label} onClick={() => onView(label === "Study" ? "opportunities" : "chat")} className="group rounded-[20px] bg-white p-5 text-left card-border transition hover:-translate-y-1 hover:shadow-lg"><div className={`flex h-11 w-11 items-center justify-center rounded-xl ${tint === "teal" ? "bg-[#e8f6f3] text-[#0d9488]" : tint === "blue" ? "bg-[#e7efff] text-[#2563eb]" : tint === "amber" ? "bg-[#fff6dc] text-[#bc8610]" : "bg-[#fff0ea] text-[#df6548]"}`}><Icon size={20} /></div><h3 className="mt-5 font-bold text-[#183b56]">{label}</h3><p className="mt-1 text-sm leading-5 text-[#6c8490]">{copy}</p></button>)}</div><div className="mt-10 grid gap-5 lg:grid-cols-[1fr_1fr]"><div className="rounded-[24px] bg-white p-6 card-border"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#8aa0a8]">Upcoming deadlines</p><h3 className="mt-2 text-xl font-bold">Keep momentum</h3></div><button onClick={() => onView("applications")} className="text-xs font-bold text-[#0f766e]">View all</button></div><div className="mt-5 space-y-3">{upcomingDeadlines.length ? upcomingDeadlines.slice(0, 4).map(d => <Deadline key={d.id} title={d.title} org={d.org} date={d.date} urgent={d.urgent} />) : <p className="text-sm text-[#8aa0a8]">Nothing due in the next {DEADLINE_REMINDER_DAYS} days — you're on top of it.</p>}</div></div><div className="rounded-[24px] bg-[#dff7e8] p-6"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-full bg-white text-[#258044]"><Target size={19} /></div><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#258044]">One small move</p><h3 className="mt-1 text-lg font-bold text-[#183b56]">Check one programme today</h3></div></div><p className="mt-5 text-sm leading-6 text-[#52717d]">A little progress counts. Start by saving one opportunity that feels realistic for where you are now.</p><button onClick={() => onView("opportunities")} className="mt-5 inline-flex items-center gap-2 text-sm font-bold text-[#258044]">Find an opportunity <ArrowRight size={16} /></button></div></div></div> }
function Deadline({ title, org, date, urgent }: { title: string; org: string; date: Date; urgent?: boolean }) { return <div className="flex items-center gap-3 rounded-2xl bg-[#f7fafc] p-3"><div className="flex h-10 w-10 flex-col items-center justify-center rounded-xl bg-white text-[#183b56] shadow-sm"><span className="text-[9px] font-bold uppercase text-[#8aa0a8]">{date.toLocaleDateString(undefined, { month: "short" })}</span><span className="text-sm font-bold">{date.getDate()}</span></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{title}</p><p className="truncate text-xs text-[#8aa0a8]">{org}</p></div>{urgent && <Pill color="coral">Soon</Pill>}</div> }
function Chat({ chat, input, setInput, send, pathwayDraft, onSavePathway, pathwaySaveStatus, prompts, promptOpen, setPromptOpen, conversations, onOpenConversation, onNewChat }: { chat: { from: string; text: string }[]; input: string; setInput: (s: string) => void; send: (s?: string) => void; pathwayDraft: any; onSavePathway: () => void; pathwaySaveStatus: "idle" | "saving" | "saved"; prompts: { id: number; category: string; promptText: string; displayOrder: number }[]; promptOpen: boolean; setPromptOpen: (open: boolean) => void; conversations: { id: number; title: string | null; updatedAt: Date }[]; onOpenConversation: (id: number) => void; onNewChat: () => void }) { const canSave = canOfferSavePathway(pathwayDraft); const saveDisabled = !canSave || pathwaySaveStatus !== "idle"; const saveLabel = pathwaySaveStatus === "saved" ? "Saved" : pathwaySaveStatus === "saving" ? "Saving..." : canSave ? "Save this pathway" : "Pathway details needed before saving";
  // Rendered twice: inline on mobile/tablet (the showcase aside is desktop-only, so this is
  // otherwise unreachable below lg) and inside the desktop showcase aside — same markup, same
  // save button, never two diverging copies of this logic.
  const pathwayCard = <div className="rounded-2xl bg-white p-4">{pathwayDraft ? <><p className="text-[10px] font-bold uppercase tracking-[.14em] text-[#8aa0a8]">Your generated pathway</p><h3 className="mt-2 text-lg font-bold leading-snug text-[#183b56]">{pathwayDraft.recommended_direction}</h3>{pathwayDraft.reasons && <p className="mt-2 text-xs leading-5 text-[#6c8490]">{pathwayDraft.reasons}</p>}{Array.isArray(pathwayDraft.next_steps) && pathwayDraft.next_steps.length > 0 && <ul className="mt-3 space-y-1.5">{pathwayDraft.next_steps.slice(0, 4).map((step: string, i: number) => <li key={i} className="flex gap-2 text-xs leading-5 text-[#52717d]"><span className="mt-0.5 text-[#0d9488]">•</span>{step}</li>)}</ul>}</> : <p className="text-xs leading-5 text-[#6c8490]">Keep chatting — once we know your goal, education, interests or skills, province and main constraint, your personalised pathway will appear here.</p>}<button disabled={saveDisabled} onClick={onSavePathway} className={`mt-4 flex w-full items-center justify-center gap-2 rounded-full px-4 py-2.5 text-xs font-bold transition ${pathwaySaveStatus === "saved" ? "bg-[#dff7e8] text-[#258044]" : saveDisabled ? "cursor-not-allowed bg-[#edf4f5] text-[#9ab0b6]" : "bg-[#0d9488] text-white hover:bg-[#0b7f75]"}`}>{pathwaySaveStatus === "saved" && <Check size={14} />}{saveLabel}</button></div>;
  return <div className="grid w-full min-w-0 gap-5 lg:grid-cols-[minmax(180px,20fr)_minmax(0,55fr)_minmax(220px,25fr)]"><aside className="hidden rounded-[22px] bg-white p-4 card-border lg:block"><p className="text-[10px] font-bold uppercase tracking-[.14em] text-[#8aa0a8]">Chat workspace</p><button onClick={onNewChat} className="mt-4 flex w-full items-center gap-2 rounded-xl bg-[#e8f6f3] px-3 py-3 text-left text-xs font-bold text-[#0f766e]">+ New chat</button><button onClick={() => setPromptOpen(true)} className="mt-2 flex w-full items-center gap-2 rounded-xl px-3 py-3 text-left text-xs font-bold text-[#52717d] hover:bg-[#f7fafc]">Prompt Library</button><p className="mt-6 text-[10px] font-bold uppercase tracking-[.14em] text-[#8aa0a8]">Past chats</p><div className="mt-2 space-y-1">{conversations.slice(0, 5).map(c => <button key={c.id} onClick={() => onOpenConversation(c.id)} className="w-full truncate rounded-lg px-2 py-2 text-left text-xs text-[#52717d] hover:bg-[#f7fafc]">{c.title || "Untitled chat"}</button>)}</div></aside><section className="min-w-0"><div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><Pill color="teal"><Sparkles size={13} className="mr-1" /> Your career guide</Pill><h1 className="font-display mt-4 text-4xl tracking-[-.04em]">Let’s find a direction<br /><span className="text-[#0d9488]">that feels like you.</span></h1><p className="mt-3 text-[#6c8490]">One question at a time. No pressure to have the perfect answer.</p></div><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={onNewChat}>+ New chat</Button>{conversations.length > 0 && <select aria-label="Reopen a previous conversation" onChange={e => e.target.value && onOpenConversation(Number(e.target.value))} className="h-10 rounded-full border border-[#dce9ea] bg-white px-3 text-xs font-bold text-[#52717d]"><option value="">Past chats</option>{conversations.slice(0, 5).map(c => <option key={c.id} value={c.id}>{c.title || "Untitled chat"}</option>)}</select>}<Button variant="outline" onClick={() => setPromptOpen(!promptOpen)}><Lightbulb size={16} /> Prompt library</Button></div></div>{/* The showcase aside below is desktop-only (hidden lg:block) — without this, the pathway card and Save button would be completely unreachable on mobile/tablet, not just re-laid-out. */}<div className="mb-6 lg:hidden">{pathwayCard}</div>{promptOpen && <div className="mb-4 rounded-[22px] bg-[#e8f6f3] p-5"><div className="flex items-center justify-between"><div><p className="text-sm font-bold text-[#183b56]">Try a starter prompt</p><p className="mt-1 text-[11px] text-[#6c8490]">Read-only starter prompts curated by PathFinder.</p></div><button onClick={() => setPromptOpen(false)} className="text-xs font-bold text-[#0f766e]">Close</button></div><div className="mt-4 grid gap-2 sm:grid-cols-2">{prompts.map(p => <button key={p.id} onClick={() => { setPromptOpen(false); send(p.promptText); }} className="rounded-xl bg-white p-3 text-left text-xs leading-5 text-[#52717d] transition hover:text-[#0f766e]"> <span className="mb-1 block text-[10px] font-bold uppercase tracking-[.12em] text-[#8aa0a8]">{p.category}</span>{p.promptText}</button>)}</div></div>}<div className="rounded-[26px] bg-white p-4 card-border sm:p-7"><div className="h-[420px] overflow-y-auto space-y-5">{chat.map((m, i) => <div key={i} className={`flex gap-3 ${m.from === "user" ? "justify-end" : ""}`}>{m.from === "ai" && <div className="mt-1 flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-[#dff7f1] text-[#0d9488]"><Sparkles size={16} /></div>}<div className={`max-w-[78%] rounded-[20px] px-4 py-3 text-sm leading-6 ${m.from === "ai" ? "rounded-tl-sm bg-[#f7fafc] text-[#52717d]" : "rounded-tr-sm bg-[#0d9488] text-white"}`}><Streamdown>{m.text}</Streamdown></div></div>)}</div><div className="mt-6 flex flex-wrap items-center gap-2"><button onClick={() => send("Study")} className="rounded-full bg-[#e8f6f3] px-3 py-2 text-xs font-bold text-[#0f766e]">🎓 Study</button><button onClick={() => send("Work")} className="rounded-full bg-[#e7efff] px-3 py-2 text-xs font-bold text-[#2563eb]">💼 Work</button><button onClick={() => send("Skills")} className="rounded-full bg-[#fff6dc] px-3 py-2 text-xs font-bold text-[#a77408]">🛠 Skills</button><button onClick={() => send("I’m not sure yet")} className="rounded-full bg-[#edf4f5] px-3 py-2 text-xs font-bold text-[#52717d]">🧭 Explore</button></div><div className="sticky bottom-0 mt-4 flex items-center gap-2 rounded-2xl border border-[#dce9ea] bg-white p-2 focus-within:border-[#0d9488]"><input value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === "Enter" && send()} placeholder="Type whatever is on your mind..." className="min-w-0 flex-1 bg-transparent px-3 text-sm outline-none placeholder:text-[#9ab0b6]" /><button onClick={() => send()} className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#0d9488] text-white"><ArrowRight size={18} /></button></div><p className="mt-4 text-center text-[11px] text-[#9ab0b6]">PathFinder offers guidance, not guarantees. Always verify requirements with the official source.</p></div></section><aside className="hidden min-w-0 rounded-[22px] bg-[#e8f6f3] p-5 lg:block"><PathMarker label="Your next move" /><div className="mt-5">{pathwayCard}</div><h2 className="font-display mt-6 text-2xl leading-tight text-[#183b56]">Keep the route small.</h2><p className="mt-3 text-sm leading-6 text-[#52717d]">Use one conversation to clarify a direction, then carry the next practical step into My Pathways.</p><div className="mt-6 space-y-3"><div className="rounded-2xl bg-white/80 p-3"><p className="text-xs font-bold text-[#183b56]">1. Ask honestly</p><p className="mt-1 text-xs leading-5 text-[#6c8490]">Share what matters, including constraints.</p></div><div className="rounded-2xl bg-white/80 p-3"><p className="text-xs font-bold text-[#183b56]">2. Check the why</p><p className="mt-1 text-xs leading-5 text-[#6c8490]">Look for the reasoning behind a suggestion.</p></div><div className="rounded-2xl bg-white/80 p-3"><p className="text-xs font-bold text-[#183b56]">3. Choose one move</p><p className="mt-1 text-xs leading-5 text-[#6c8490]">Turn the conversation into something doable.</p></div></div></aside></div> }
function Opportunities({ sourceMessage, filtered, query, setQuery, category, setCategory, province, setProvince, saved, savedItems, toggleSave }: { sourceMessage: string; filtered: any[]; query: string; setQuery: (s: string) => void; category: string; setCategory: (s: string) => void; province: string; setProvince: (s: string) => void; saved: (number | string)[]; savedItems: { id: number; snapshotData: string | null }[]; toggleSave: (id: number) => void }) { return <div><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><Pill color="blue">Opportunity hub</Pill><h1 className="font-display mt-4 text-4xl tracking-[-.04em]">Find something<br /><span className="text-[#0d9488]">worth moving towards.</span></h1><p className="mt-3 text-[#6c8490]">Curated opportunities with a real source to verify before you apply.</p></div><Pill color="green"><Bookmark size={13} className="mr-1" /> {saved.length} saved</Pill></div><div className="mt-8 flex flex-col gap-3 sm:flex-row"><div className="flex flex-1 items-center gap-3 rounded-2xl bg-white px-4 card-border"><Search size={18} className="text-[#8aa0a8]" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search opportunities, skills or organisations" className="h-12 flex-1 bg-transparent text-sm outline-none" /></div><select value={category} onChange={e => setCategory(e.target.value)} className="h-12 rounded-2xl border border-[#dce9ea] bg-white px-4 text-sm font-bold text-[#52717d] outline-none"><option>All</option><option>Study</option><option>Work</option><option>Skills</option><option>Business</option></select><select value={province} onChange={e => setProvince(e.target.value)} className="h-12 rounded-2xl border border-[#dce9ea] bg-white px-4 text-sm font-bold text-[#52717d] outline-none"><option>All</option><option>Gauteng</option><option>Western Cape</option><option>KwaZulu-Natal</option><option>Eastern Cape</option><option>National</option></select></div><p className="mt-4 text-xs text-[#8aa0a8]">{sourceMessage} Always verify requirements on the linked source.</p>{savedItems.length > 0 && <div className="mt-5 rounded-[22px] bg-[#e8f6f3] p-4"><p className="text-xs font-bold uppercase tracking-[.12em] text-[#0f766e]">Saved for later</p><div className="mt-3 flex flex-wrap gap-2">{savedItems.slice(0, 4).map(item => { let snap: any = {}; try { snap = JSON.parse(item.snapshotData || "{}"); } catch {} return <span key={item.id} className="rounded-full bg-white px-3 py-2 text-xs font-bold text-[#52717d]">{snap.title || snap.name || "Saved opportunity"}</span>; })}</div></div>}<div className="mt-5 grid gap-4 md:grid-cols-2">{filtered.map(o => <div key={o.id} className="group rounded-[22px] bg-white p-5 card-border transition hover:-translate-y-1 hover:shadow-xl hover:shadow-[#183b56]/[.06]"><div className="flex items-start justify-between gap-4"><Pill color={o.tone}>{o.category}</Pill><button onClick={() => toggleSave(o.id)} className={(saved.includes(o.id) || saved.includes(o.sourceUrl)) ? "text-[#0d9488]" : "text-[#b1c2c5] hover:text-[#0d9488]"} aria-label={`Save ${o.title}`}><Bookmark size={19} fill={(saved.includes(o.id) || saved.includes(o.sourceUrl)) ? "currentColor" : "none"} /></button></div><h3 className="mt-5 font-display text-2xl leading-tight">{o.title}</h3><p className="mt-1 text-sm font-bold text-[#52717d]">{o.org}</p><p className="mt-3 text-sm leading-6 text-[#6c8490]">{o.desc}</p><div className="mt-4 flex flex-wrap gap-2">{o.tags.map((t: string) => <span key={t} className="rounded-full bg-[#f7fafc] px-2.5 py-1 text-[11px] font-semibold text-[#6c8490]">{t}</span>)}</div><div className="mt-5 flex items-center justify-between border-t border-[#edf3f3] pt-4"><div className="flex items-center gap-1 text-xs font-semibold text-[#8aa0a8]"><MapPin size={13} /> {o.place}</div><div className="flex items-center gap-2"><span className="text-xs font-bold text-[#258044]">{o.score}% match</span><ChevronRight size={16} className="text-[#0d9488]" /></div></div><a href={o.sourceUrl || "#"} target="_blank" rel="noreferrer" className="mt-4 inline-flex items-center gap-2 text-sm font-bold text-[#0f766e]">Verify / Apply <ArrowRight size={15} /></a></div>)}</div>{filtered.length === 0 && <div className="rounded-[22px] bg-white p-10 text-center card-border"><Search className="mx-auto text-[#b1c2c5]" /><h3 className="mt-4 font-bold">No opportunities found</h3><p className="mt-2 text-sm text-[#6c8490]">Try a wider search or another category.</p></div>}</div> }
function Plan({ setView, savedPathways, selectedPathwayId, onSelectPathway, checklist, onToggleChecklist }: { setView: (s: string) => void; savedPathways: { id: number; recommendedDirection: string | null; goal: string | null; matchScore: number | null; reasons: string | null; immediateAction: string | null; alternativeOptions: string | null; createdAt: Date }[]; selectedPathwayId?: number; onSelectPathway: (id: number) => void; checklist: { id: number; text: string; isComplete: number; isCustom: number }[]; onToggleChecklist: (id: number, complete: number) => Promise<void> }) {
  // Everything below is sourced from the authenticated user's own saved pathway rows and their
  // real checklist — a fresh, zero-engagement account has neither, and must show an honest empty
  // state rather than any placeholder progress, checklist, or match content.
  const activePathway = savedPathways.find(p => p.id === selectedPathwayId) || savedPathways[0];
  const [steps, setSteps] = useState<any[]>([]);
  const [customStep, setCustomStep] = useState("");
  useEffect(() => { setSteps(checklist.map(item => ({ id: item.id, title: item.text, detail: item.isCustom ? "Added by you" : "Saved pathway milestone", done: Boolean(item.isComplete), custom: Boolean(item.isCustom) }))); }, [checklist]);
  const completed = steps.filter(s => s.done).length;
  const percent = steps.length ? Math.round((completed / steps.length) * 100) : 0;
  if (!activePathway) return <div><PathMarker label="My Pathways" /><div className="mt-4"><h1 className="font-display text-4xl tracking-[-.04em]">Small moves,<br /><span className="text-[#0d9488]">real momentum.</span></h1><p className="mt-3 text-[#6c8490]">Your pathway checklist keeps the next step visible without making it feel heavy.</p></div><div className="mt-10 rounded-[24px] bg-white p-10 text-center card-border"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-[#e8f6f3] text-[#0d9488]"><Target size={24} /></div><h2 className="mt-5 text-xl font-bold text-[#183b56]">You haven’t saved a pathway yet</h2><p className="mx-auto mt-2 max-w-[420px] text-sm leading-6 text-[#6c8490]">Start a conversation to find your direction — once you and your guide reach a real, personalised pathway, you can save it from there.</p><Button className="mt-6" onClick={() => setView("chat")}>Start a conversation <ArrowRight size={16} /></Button></div></div>;
  return <div><PathMarker label="My Pathways" /><div className="mt-2"><Pill color="green"><Target size={13} className="mr-1" /> Active route</Pill></div><div className="mt-4 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><h1 className="font-display text-4xl tracking-[-.04em]">Small moves,<br /><span className="text-[#0d9488]">real momentum.</span></h1><p className="mt-3 text-[#6c8490]">Your pathway checklist keeps the next step visible without making it feel heavy.</p></div><div className="rounded-2xl bg-white px-5 py-3 card-border"><span className="text-2xl font-bold text-[#0d9488]">{percent}%</span><span className="ml-2 text-xs font-bold uppercase tracking-wider text-[#8aa0a8]">complete</span></div></div>{savedPathways.length > 1 && <div className="mt-8 rounded-[22px] bg-white p-5 card-border"><p className="text-xs font-bold uppercase tracking-[.12em] text-[#8aa0a8]">Saved pathways</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{savedPathways.map(path => <button key={path.id} onClick={() => onSelectPathway(path.id)} className={`rounded-xl p-3 text-left transition ${activePathway.id === path.id ? "bg-[#e8f6f3] ring-1 ring-[#0d9488]" : "bg-[#f7fafc] hover:bg-[#edf4f5]"}`}><p className="text-sm font-bold text-[#183b56]">{path.recommendedDirection || path.goal || "Saved direction"}</p><p className="mt-1 text-xs text-[#0f766e]">{path.matchScore != null ? `${path.matchScore}% match` : "Personalised pathway"}</p></button>)}</div></div>}<div className="mt-10 grid gap-5 lg:grid-cols-[1fr_.7fr]"><div className="rounded-[24px] bg-white p-6 card-border"><div className="flex items-center justify-between"><h2 className="text-xl font-bold">Your next steps</h2><Pill color="teal">{steps.length} milestone{steps.length === 1 ? "" : "s"}</Pill></div>{steps.length > 0 ? <><div className="mt-5 h-2 overflow-hidden rounded-full bg-[#e6efef]"><div className="h-full rounded-full bg-[#22c55e] transition-all" style={{ width: `${percent}%` }} /></div><div className="mt-7 space-y-1">{steps.map((s, i) => <label key={`${s.title}-${i}`} className="flex cursor-pointer gap-4 rounded-2xl p-3 transition hover:bg-[#f7fafc]"><input type="checkbox" checked={s.done} onChange={async () => { const nextDone = !s.done; setSteps(list => list.map((x, idx) => idx === i ? { ...x, done: nextDone } : x)); if (s.id) await onToggleChecklist(s.id, nextDone ? 1 : 0); }} className="sr-only" /><div className={`mt-1 flex h-8 w-8 shrink-0 items-center justify-center rounded-full ${s.done ? "bg-[#dff7e8] text-[#258044]" : "border-2 border-[#cfe1e3] text-[#8aa0a8]"}`}>{s.done ? <Check size={15} /> : <span className="text-xs font-bold">{i + 1}</span>}</div><div><h3 className={`text-sm font-bold ${s.done ? "text-[#52717d] line-through decoration-[#b1c2c5]" : "text-[#183b56]"}`}>{s.title}</h3><p className="mt-1 text-xs text-[#8aa0a8]">{s.custom ? "Your custom step" : s.detail}</p></div></label>)}</div></> : <p className="mt-5 text-sm leading-6 text-[#8aa0a8]">No checklist steps saved for this pathway yet.</p>}<div className="mt-5 flex gap-2"><input value={customStep} onChange={e => setCustomStep(e.target.value)} placeholder="Add your own step" className="h-11 flex-1 rounded-xl border border-[#dce9ea] px-3 text-sm outline-none focus:border-[#0d9488]" /><Button onClick={() => { if (customStep.trim()) { setSteps(list => [...list, { title: customStep.trim(), detail: "Added by you", done: false, custom: true }]); setCustomStep(""); } }}>Add</Button></div></div><div className="rounded-[24px] bg-[#183b56] p-6 text-white"><Pill color="teal">Your match explained</Pill><h2 className="font-display mt-5 text-3xl">{activePathway.matchScore != null ? `${activePathway.matchScore}% match` : "Personalised pathway"}</h2><p className="mt-4 text-sm leading-6 text-white/65">{activePathway.reasons || "The reasoning behind this direction will appear here once your guide has enough context to explain it."}</p><div className="mt-7 space-y-3 text-sm">{activePathway.immediateAction && <div className="flex items-start justify-between gap-4"><span className="shrink-0 text-white/55">Immediate action</span><strong className="text-right text-[#8de3d6]">{activePathway.immediateAction}</strong></div>}{activePathway.alternativeOptions && <div className="flex items-start justify-between gap-4"><span className="shrink-0 text-white/55">Alternative options</span><strong className="text-right text-[#8de3d6]">{activePathway.alternativeOptions}</strong></div>}<div className="flex items-center justify-between"><span className="text-white/55">Saved</span><strong className="text-[#8de3d6]">{new Date(activePathway.createdAt).toLocaleDateString()}</strong></div></div><button onClick={() => setView("opportunities")} className="mt-8 flex items-center gap-2 text-sm font-bold text-[#8de3d6]">See matching opportunities <ArrowRight size={16} /></button></div></div></div>;
}
