function Stat({ label, value }: { label: string; value: string }) { return <div className="rounded-[20px] bg-white p-5 card-border"><p className="text-xs font-bold uppercase tracking-[.12em] text-[#8aa0a8]">{label}</p><p className="mt-3 font-display text-3xl text-[#183b56]">{value}</p></div> }

export default function Home() { const [location] = useLocation(); const [entered, setEntered] = useState(location === "/workspace"); return entered ? <Workspace onExit={() => setEntered(false)} /> : <Landing onEnter={() => setEntered(true)} />; }

function SavedPage({ savedItems, onToggle }: { savedItems: { id: number; opportunityId: number | null; snapshotData: string | null }[]; onToggle: (item: { id: number; opportunityId: number | null; snapshotData: string | null }) => void }) { return <div><div className="flex items-end justify-between gap-4"><div><Pill color="teal"><Heart size={13} className="mr-1" /> Saved opportunities</Pill><h1 className="font-display mt-4 text-4xl tracking-[-.04em]">Your shortlist,<br /><span className="text-[#0d9488]">all in one place.</span></h1><p className="mt-3 text-[#6c8490]">Keep the opportunities you want to verify and revisit.</p></div><span className="rounded-full bg-white px-3 py-2 text-xs font-bold text-[#0f766e] card-border">{savedItems.length} saved</span></div>{savedItems.length === 0 ? <div className="mt-10 rounded-[24px] bg-white p-10 text-center card-border"><Heart className="mx-auto text-[#b1c2c5]" /><h2 className="mt-4 font-bold">Nothing saved yet</h2><p className="mt-2 text-sm text-[#6c8490]">Save an opportunity from Search opportunities and it will appear here.</p></div> : <div className="mt-8 grid gap-4 md:grid-cols-2">{savedItems.map(item => { let snap: any = {}; try { snap = JSON.parse(item.snapshotData || "{}"); } catch {} return <div key={item.id} className="rounded-[22px] bg-white p-5 card-border"><div className="flex items-start justify-between gap-3"><Pill color="teal">{snap.category || "Opportunity"}</Pill><button aria-label={`Remove ${snap.title || snap.name || "saved opportunity"}`} onClick={() => onToggle(item)} className="text-[#0d9488]"><Bookmark size={19} fill="currentColor" /></button></div><h2 className="font-display mt-5 text-2xl">{snap.title || snap.name || "Saved opportunity"}</h2><p className="mt-1 text-sm font-bold text-[#52717d]">{snap.org || snap.organisation || "Official source"}</p><p className="mt-3 text-sm leading-6 text-[#6c8490]">{snap.desc || snap.description || "Review the official source for current requirements."}</p><a href={snap.sourceUrl} target="_blank" rel="noreferrer" className="mt-5 inline-flex items-center gap-2 text-sm font-bold text-[#0f766e]">Verify / Apply <ArrowRight size={15} /></a></div>})}</div>}</div> }

function AdminOpportunities() { const list = trpc.opportunities.adminList.useQuery(); const update = trpc.opportunities.adminUpdate.useMutation(); const [selected, setSelected] = useState<any>(null); const [form, setForm] = useState({ name: "", organisation: "", description: "", sourceUrl: "", province: "", deadlineDate: "" }); const utils = trpc.useUtils(); const open = (item: any) => { setSelected(item); setForm({ name: item.name, organisation: item.organisation, description: item.description, sourceUrl: item.sourceUrl, province: item.province || "", deadlineDate: item.deadlineDate ? new Date(item.deadlineDate).toISOString().slice(0, 10) : "" }); }; return <div><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><Pill color="teal"><Settings2 size={13} className="mr-1" /> Admin workspace</Pill><h1 className="font-display mt-4 text-4xl tracking-[-.04em]">Keep opportunities<br /><span className="text-[#0d9488]">fresh and trustworthy.</span></h1><p className="mt-3 text-[#6c8490]">Edit curated records, verify source links, and keep learner-facing information current.</p></div><Pill color="green">{list.data?.length || 0} records</Pill></div><div className="mt-8 grid gap-4 lg:grid-cols-[1fr_.8fr]"> <div className="space-y-3">{(list.data || []).map(item => <button key={item.id} onClick={() => open(item)} className={`w-full rounded-[20px] bg-white p-5 text-left card-border transition hover:-translate-y-0.5 ${selected?.id === item.id ? "ring-2 ring-[#0d9488]" : ""}`}><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.12em] text-[#8aa0a8]">{item.category}</p><h3 className="mt-2 font-bold text-[#183b56]">{item.name}</h3><p className="mt-1 text-xs text-[#6c8490]">{item.organisation} · {item.province || "National"}</p></div><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${item.verificationStatus === "verified" ? "bg-[#e8f6f3] text-[#0f766e]" : "bg-[#fff6dc] text-[#a77408]"}`}>{item.verificationStatus === "verified" ? "Verified" : "Needs review"}</span></div><p className="mt-4 text-xs text-[#8aa0a8]">Updated {new Date(item.sourceUpdatedAt).toLocaleDateString()}</p></button>)}</div>{selected ? <div className="rounded-[24px] bg-white p-6 card-border"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.12em] text-[#8aa0a8]">Editing record</p><h2 className="mt-2 text-xl font-bold">{selected.name}</h2></div><button aria-label="Close editor" onClick={() => setSelected(null)}><X size={18} /></button></div><div className="mt-5 space-y-3"><input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} className="h-11 w-full rounded-xl border border-[#dce9ea] px-3 text-sm" placeholder="Opportunity name" /><input value={form.organisation} onChange={e => setForm({ ...form, organisation: e.target.value })} className="h-11 w-full rounded-xl border border-[#dce9ea] px-3 text-sm" placeholder="Organisation" /><textarea value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} className="min-h-[120px] w-full rounded-xl border border-[#dce9ea] p-3 text-sm" placeholder="Description" /><input value={form.sourceUrl} onChange={e => setForm({ ...form, sourceUrl: e.target.value })} className="h-11 w-full rounded-xl border border-[#dce9ea] px-3 text-sm" placeholder="Verified HTTPS source URL" /><select value={selected.verificationStatus || "needs_review"} onChange={e => setSelected({ ...selected, verificationStatus: e.target.value })} className="h-11 w-full rounded-xl border border-[#dce9ea] bg-white px-3 text-sm"><option value="needs_review">Needs review</option><option value="verified">Verified</option></select><div className="grid gap-3 sm:grid-cols-2"><input value={form.province} onChange={e => setForm({ ...form, province: e.target.value })} className="h-11 w-full rounded-xl border border-[#dce9ea] px-3 text-sm" placeholder="Province" /><input type="date" value={form.deadlineDate} onChange={e => setForm({ ...form, deadlineDate: e.target.value })} className="h-11 w-full rounded-xl border border-[#dce9ea] px-3 text-sm" /></div></div><Button className="mt-5" onClick={async () => { await update.mutateAsync({ id: selected.id, name: form.name, organisation: form.organisation, description: form.description, sourceUrl: form.sourceUrl, verificationStatus: selected.verificationStatus || "needs_review", province: form.province, deadlineDate: form.deadlineDate ? new Date(form.deadlineDate) : null }); await utils.opportunities.adminList.invalidate(); setSelected(null); }}>Save and refresh source date</Button></div> : <div className="rounded-[24px] bg-[#183b56] p-6 text-white"><Pill color="teal">Source hygiene</Pill><h2 className="font-display mt-5 text-3xl">Trust is part of the product.</h2><p className="mt-4 text-sm leading-6 text-white/65">Every curated record must keep a real HTTPS source. Updating a record refreshes its source date so the team can monitor freshness over time.</p></div>}</div></div> }

function PathMarker({ label }: { label: string }) { return <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.16em] text-[#0f766e]"><span className="relative flex h-5 w-12 items-center"><span className="absolute left-0 h-2.5 w-2.5 rounded-full bg-[#0d9488] ring-4 ring-[#dff7f1]" /><span className="absolute left-4 h-px w-7 bg-[#91d7ce]" /><span className="absolute right-0 h-2.5 w-2.5 rounded-full border-2 border-[#0d9488] bg-white" /></span>{label}</div>
}
